/**
 * @name Unsafe deserialization from remote input
 * @description Taint flow from remote sources into pickle.load/loads
 * @kind path-problem
 * @problem.severity error
 * @id py/unsafe-deser-remote-aiohttp
 * @tags security
 *        external/cwe/cwe-502
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module DeserConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("pickle").getMember(["load", "loads"]).getACall()
      and sink = call.getArg(0)
    )
  }
}

module DeserFlow = TaintTracking::Global<DeserConfig>;
import DeserFlow::PathGraph

from DeserFlow::PathNode source, DeserFlow::PathNode sink
where DeserFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Unsafe deserialization from $@.", source.getNode(), "user input"

/**
 * @name Path traversal from remote source to file access
 * @description Untrusted input reaching file path arguments can lead to arbitrary file read/write
 * @kind path-problem
 * @problem.severity error
 * @id py/path-traversal-aiohttp
 * @tags security
 *        external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts

module PathTravConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(FileSystemAccess fa |
      sink = fa.getAPathArgument()
    )
  }
}

module PathTravFlow = TaintTracking::Global<PathTravConfig>;
import PathTravFlow::PathGraph

from PathTravFlow::PathNode source, PathTravFlow::PathNode sink
where PathTravFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Path traversal from $@.", source.getNode(), "user input"

